    flex-direction: column;
    text-align: center;
  }

  /* Newsletter */
  .newsletter-form {
    flex-direction: column;
  }

  /* Footer */
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer-bottom a {
    border-right: none;
  }

  /* Cards */
  .insight-mini {
    flex-direction: column;
  }

  .insight-mini-img {
    width: 100%;
    height: 160px;
  }

  .what-we-do-grid {
    grid-template-columns: 1fr;
  }

  .partnership-highlight {
    padding: 28px;
  }

  .capability-card {
    padding: 24px;
  }

  .carousel-slide {
    flex: 0 0 100%;
